import pytest
from orders.api import checkout


def mock_charge(total):
    return True


def test_checkout_without_coupon():
    request = {
        "items": [
            {"sku": "item1", "qty": 1},
            {"sku": "item2", "qty": 2}
        ]
    }
    stock = {"item1": 10, "item2": 10}
    status_code, response = checkout(request, stock, mock_charge)
    assert status_code == 200
    assert "total_cents" in response

