import pytest
from orders.inventory import reserve, OutOfStock

def test_reserve_in_stock():
    stock = {'item1': 5}
    reserve(stock, 'item1', 5)  # Should not raise an exception
    assert stock['item1'] == 0  # Stock should be reduced to 0


def test_reserve_out_of_stock():
    stock = {'item1': 5}
    with pytest.raises(OutOfStock):
        reserve(stock, 'item1', 6)  # Should raise OutOfStock

