from orders.inventory import reserve, OutOfStock

def test_reserve_out_of_stock():
    stock = {'SKU-77': 1}
    try:
        reserve(stock, 'SKU-77', 2)
    except OutOfStock as e:
        assert str(e) == 'SKU-77: wanted 2, have 1'
    else:
        assert False, 'Expected OutOfStock exception not raised'

