from orders.inventory import reserve, release, OutOfStock

def test_negative_stock():
    stock = {'SKU-1': 5}
    reserve(stock, 'SKU-1', 5)
    assert stock['SKU-1'] == 0
    release(stock, 'SKU-1', 5)
    assert stock['SKU-1'] == 5
    try:
        reserve(stock, 'SKU-1', 6)
    except OutOfStock:
        assert True
    else:
        assert False

